// The publisher's half, as localrouter's model seeding does it (twin-world cookbook/localrouter/seed.mjs): the
// repository created by the API, its history pushed to git-receive-pack, its LFS object uploaded by the batch API.
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { mkdtempSync, mkdirSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
if (!process.env.VOLTER_WORLD) throw new Error('Run this app through its World.');
const base = 'https://huggingface.co';
const auth = { authorization: `Bearer ${process.env.HF_TOKEN}` };
async function request(url, init = {}) {
  const response = await fetch(url, init);
  if (!response.ok) throw new Error(`${init.method ?? 'GET'} ${url}: ${response.status} ${await response.text()}`);
  return response;
}
const created = await (await request(`${base}/api/repos/create`, { method: 'POST', headers: { ...auth, 'content-type': 'application/json' }, body: JSON.stringify({ name: 'transfer-fixture', type: 'model' }) })).json();
const repo = created.name;
assert.ok(repo.endsWith('/transfer-fixture'), JSON.stringify(created));
assert.equal(created.url, `${base}/${repo}`);

const work = mkdtempSync(join(tmpdir(), 'hub-fixture-'));
const git = (args, input) => {
  const result = spawnSync('git', ['-C', work, '-c', 'user.name=Ada', '-c', 'user.email=ada@example.test', ...args], { input, maxBuffer: 64 * 1024 * 1024 });
  if (result.status !== 0) throw new Error(result.stderr.toString());
  return result.stdout;
};
const blob = Buffer.from('Hugging Face transfer fixture\n'.repeat(140)).subarray(0, 4096);
const oid = createHash('sha256').update(blob).digest('hex');
git(['init', '-q', '-b', 'main']);
writeFileSync(join(work, 'config.json'), JSON.stringify({ fixture: 'transfer-v1', bytes: blob.length }));
writeFileSync(join(work, '.gitattributes'), '*.bin filter=lfs diff=lfs merge=lfs -text\n');
mkdirSync(join(work, 'artifacts'));
writeFileSync(join(work, 'artifacts/download-fixture.bin'), `version https://git-lfs.github.com/spec/v1\noid sha256:${oid}\nsize ${blob.length}\n`);
git(['add', '.']);
git(['commit', '-q', '-m', 'Publish the cache transfer fixture']);
const revision = git(['rev-parse', 'HEAD']).toString().trim();
const pack = git(['pack-objects', '--stdout', '--revs'], `${revision}\n`);
const line = Buffer.from(`${'0'.repeat(40)} ${revision} refs/heads/main\0report-status\n`);
const command = Buffer.concat([Buffer.from((line.length + 4).toString(16).padStart(4, '0')), line, Buffer.from('0000'), pack]);
const pushed = await (await request(`${base}/${repo}.git/git-receive-pack`, { method: 'POST', headers: { ...auth, 'content-type': 'application/x-git-receive-pack-request' }, body: command })).text();
assert.ok(pushed.includes('unpack ok') && pushed.includes('ok refs/heads/main'), pushed);
const batch = await (await request(`${base}/${repo}.git/info/lfs/objects/batch`, { method: 'POST', headers: { ...auth, 'content-type': 'application/vnd.git-lfs+json' }, body: JSON.stringify({ operation: 'upload', transfers: ['basic'], objects: [{ oid, size: blob.length }] }) })).json();
const upload = batch.objects[0].actions?.upload;
assert.ok(upload?.href, JSON.stringify(batch));
await request(upload.href, { method: 'PUT', headers: { ...upload.header, 'content-type': 'application/octet-stream', 'content-length': String(blob.length) }, body: blob });
const artifacts = { repo, revision, artifacts: [
  { path: 'config.json', size: Buffer.byteLength(JSON.stringify({ fixture: 'transfer-v1', bytes: blob.length })), sha256: createHash('sha256').update(JSON.stringify({ fixture: 'transfer-v1', bytes: blob.length })).digest('hex') },
  { path: 'artifacts/download-fixture.bin', size: blob.length, sha256: oid },
] };
writeFileSync('artifacts.json', JSON.stringify(artifacts, null, 2) + '\n');
console.log(JSON.stringify({ published: repo, revision }));

