// The consumer's half, as localrouter's model cache downloads (cache/node.mjs:633 at 107fb5d): each artifact at its
// pinned revision, no token, redirects followed, a partial file resumed with Range and If-Range on the validator it
// kept, a complete partial adopted on 416, the bytes checked against the pinned sha256.
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
if (!process.env.VOLTER_WORLD) throw new Error('Run this app through its World.');
const pinned = JSON.parse(readFileSync('artifacts.json', 'utf8'));
const sha = (bytes) => createHash('sha256').update(bytes).digest('hex');
const results = [];
for (const spec of pinned.artifacts) {
  const url = `https://huggingface.co/${pinned.repo}/resolve/${pinned.revision}/${spec.path}`;
  const whole = await fetch(url, { redirect: 'follow' });
  assert.equal(whole.status, 200, `${spec.path}: ${whole.status}`);
  assert.equal(new URL(whole.url).protocol, 'https:');
  const validator = whole.headers.get('etag') ?? whole.headers.get('last-modified');
  assert.ok(validator, `${spec.path}: no validator`);
  const bytes = Buffer.from(await whole.arrayBuffer());
  assert.equal(bytes.length, spec.size);
  assert.equal(sha(bytes), spec.sha256);
  // an interrupted transfer resumes from the bytes it kept
  const offset = Math.floor(spec.size / 2);
  const rest = await fetch(url, { headers: { Range: `bytes=${offset}-`, 'If-Range': validator }, redirect: 'follow' });
  assert.equal(rest.status, 206, `${spec.path}: resume ${rest.status}`);
  assert.equal(rest.headers.get('content-range'), `bytes ${offset}-${spec.size - 1}/${spec.size}`);
  assert.equal(Number(rest.headers.get('content-length')), spec.size - offset);
  const resumed = Buffer.concat([bytes.subarray(0, offset), Buffer.from(await rest.arrayBuffer())]);
  assert.equal(sha(resumed), spec.sha256);
  // a partial file that already holds every byte is adopted
  const complete = await fetch(url, { headers: { Range: `bytes=${spec.size}-`, 'If-Range': validator }, redirect: 'follow' });
  assert.equal(complete.status, 416, `${spec.path}: complete offset ${complete.status}`);
  await complete.body?.cancel();
  results.push({ path: spec.path, size: spec.size, sha256: spec.sha256 });
}
console.log(JSON.stringify({ repo: pinned.repo, revision: pinned.revision, verified: results }));
